func openLockWithOperation(path string,operation int)(*os.File,error){fd,e:=syscall.Open(path,syscall.O_RDONLY|syscall.O_NOFOLLOW|syscall.O_CLOEXEC|syscall.O_DIRECTORY,0);if e!=nil{return nil,e};var st syscall.Stat_t;if e=syscall.Fstat(fd,&st);e!=nil{syscall.Close(fd);return nil,e};if st.Uid!=0||st.Mode&syscall.S_IFMT!=syscall.S_IFDIR||uint32(st.Mode&07777)!=00555{syscall.Close(fd);return nil,fmt.Errorf("lock-anchor-class")};if e=syscall.Flock(fd,operation);e!=nil{syscall.Close(fd);return nil,e};return os.NewFile(uintptr(fd),path),nil}
