func releaseLock(f *os.File){if f==nil{return};_=syscall.Flock(int(f.Fd()),syscall.LOCK_UN);_=f.Close()}
func atomicReplaceUnique(path,body,gen string,mode uint32)error{tmp:=path+".tmp."+gen;fd,e:=syscall.Open(tmp,syscall.O_WRONLY|syscall.O_CREAT|syscall.O_EXCL|syscall.O_NOFOLLOW|syscall.O_CLOEXEC,0600);if e!=nil{return e};f:=os.NewFile(uintptr(fd),tmp);cleanup:=true;defer func(){if cleanup{_=os.Remove(tmp)}}();if _,e=io.WriteString(f,body);e!=nil{_=f.Close();return e};if e=f.Sync();e!=nil{_=f.Close();return e};if e=f.Chmod(os.FileMode(mode));e!=nil{_=f.Close();return e};if e=f.Close();e!=nil{return e};if e=os.Rename(tmp,path);e!=nil{return e};cleanup=false;return nil}
