func readEvidence(path string,expectedMode uint32)([]byte,string,error){fd,e:=syscall.Open(path,syscall.O_RDONLY|syscall.O_NOFOLLOW|syscall.O_CLOEXEC,0);if e!=nil{return nil,"",e};f:=os.NewFile(uintptr(fd),path);defer f.Close();var st syscall.Stat_t;if e=syscall.Fstat(fd,&st);e!=nil{return nil,"",e};if st.Uid!=uint32(os.Getuid())||st.Mode&syscall.S_IFMT!=syscall.S_IFREG||st.Nlink!=1||uint32(st.Mode&0777)!=expectedMode{return nil,"",fmt.Errorf("evidence-class")};b,e:=io.ReadAll(io.LimitReader(f,64<<10));if e!=nil{return nil,"",e};g:=extractGeneration(string(b));if len(g)!=32{return nil,"",fmt.Errorf("generation-format")};return b,g,nil}
